package pe.edu.upeu.bomerp.inventario.service;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import lombok.RequiredArgsConstructor;import java.math.BigDecimal;import pe.edu.upeu.bomerp.inventario.model.*;import pe.edu.upeu.bomerp.inventario.repository.*;import pe.edu.upeu.bomerp.articulo.service.ArticuloService;import pe.edu.upeu.bomerp.administracion.repository.AlmacenRepository;
@Service @RequiredArgsConstructor @Transactional public class StockService {
private final LoteRepository lotes;private final ArticuloService articulos;private final AlmacenRepository almacenes;
public void validar(Long almacen,String codigo,BigDecimal cantidad){if(cantidad==null||cantidad.signum()<=0)throw new IllegalArgumentException("Cantidad debe ser positiva");if(!articulos.obtenerPorCodigo(codigo).isActivo())throw new IllegalArgumentException("Artículo inactivo");if(!almacenes.findById(almacen).filter(a->a.isActivo()).isPresent())throw new IllegalArgumentException("Almacén no existe o está inactivo");}
public Long ingresar(Long almacen,String codigo,BigDecimal cantidad,Long origen){validar(almacen,codigo,cantidad);var l=new Lote();l.setAlmacenId(almacen);l.setCodigoArticulo(codigo);l.setCantidadInicial(cantidad);l.setCantidadDisponible(cantidad);l.setMovimientoOrigenId(origen);return lotes.save(l).getId();}
public void consumir(Long almacen,String codigo,BigDecimal cantidad,Long loteId){validar(almacen,codigo,cantidad);var disponibles=lotes.bloquearDisponibles(codigo,almacen);var restante=cantidad;for(var l:disponibles){if(loteId!=null&&!l.getId().equals(loteId))continue;var retirar=l.getCantidadDisponible().min(restante);if(retirar.signum()>0){l.descontar(retirar);restante=restante.subtract(retirar);}if(restante.signum()==0)break;}if(restante.signum()>0)throw new IllegalStateException("Stock insuficiente para "+codigo+" en el almacén "+almacen);}
}
